{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0b1220;--muted:#9aa6b2;--accent:#7ad7c6;--glass:rgba(255,255,255,0.04);--glass-2:rgba(255,255,255,0.02)}
    *{box-sizing:border-box}
    body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; background:linear-gradient(180deg,var(--bg),#071018 60%); color:#e6eef3; -webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:52px;height:52px;border-radius:10px;background:linear-gradient(135deg,#0a2b2a,#07323a);display:grid;place-items:center;font-weight:700;color:var(--accent);font-size:18px}
    nav a{color:var(--muted);margin-left:18px;text-decoration:none;font-weight:600}
    .hero{padding:36px 28px 18px;display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .card{background:linear-gradient(180deg,var(--glass),var(--glass-2));padding:20px;border-radius:16px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px;font-size:28px;color:#f0fbf8}
    p.lead{margin:0;color:var(--muted)}
    .who{margin-top:18px;display:flex;gap:14px;align-items:center}
    .avatar{width:68px;height:68px;border-radius:12px;background:linear-gradient(180deg,#0f3940,#07232c);display:grid;place-items:center;color:var(--accent);font-weight:700}
    .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:18px}
    .fact{background:transparent;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.02)}
    /* Proof Gallery */
    .proof{margin-top:22px}
    .testimonial{min-height:120px;display:grid;align-content:center}
    .quote{font-style:italic;color:#dff7f0}
    .meta{margin-top:8px;color:var(--muted);font-size:13px}
    .badges{display:flex;gap:10px;margin-top:14px}
    .badge{background:linear-gradient(90deg,#082a2a,#08323a);padding:8px 10px;border-radius:10px;font-weight:600;color:var(--accent);font-size:13px;position:relative;cursor:default}
    .badge[data-tip]:focus::after,.badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#021617;padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);white-space:nowrap;font-size:12px;color:#bdfff3}
    .side-cta{display:flex;flex-direction:column;gap:12px}
    .cta-btn{background:var(--accent);color:#03201b;padding:12px 14px;border-radius:10px;text-decoration:none;text-align:center;font-weight:700}
    footer{padding:28px;color:var(--muted);font-size:13px}
    /* pattern */
    .pattern-wrap{position:absolute;right:6%;top:14%;opacity:0.08;width:420px;height:420px;pointer-events:none}
    /* small screens */
    @media (max-width:880px){.hero{grid-template-columns:1fr;}.pattern-wrap{display:none}.brand .logo{width:44px;height:44px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html" style="color:var(--accent)">About</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <section class="card">
        <h1>We tune the room for what you bring</h1>
        <p class="lead">A small team of facilitators and sound architects focused on approachable, restorative sound gatherings. We design cohesive cohorts — short series meant to land with lasting calm.</p>

        <div class="who">
          <div class="avatar">EA</div>
          <div>
            <div style="font-weight:700">Meet the team</div>
            <div style="font-size:13px;color:var(--muted)">Facilitators trained across somatic practices, breathwork, and contemporary gong language.</div>
          </div>
        </div>

        <div class="grid">
          <div class="fact"><strong>Cohort model</strong><div style="color:var(--muted);margin-top:6px">Small groups, consistent rhythm — join a standing series or a short run.</div></div>
          <div class="fact"><strong>Audio-led design</strong><div style="color:var(--muted);margin-top:6px">We craft layers of tuned bowls, chimes, and subtle electronics to support rest.</div></div>
          <div class="fact"><strong>Local & live</strong><div style="color:var(--muted);margin-top:6px">Sessions are in {{CITY}}, {{STATE}} — in-person with occasional livestreams.</div></div>
          <div class="fact"><strong>Responsibility</strong><div style="color:var(--muted);margin-top:6px">We include contraindication guidance for safety and clarity.</div></div>
        </div>

        <div class="proof card" aria-live="polite">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div style="font-weight:800">Proof Gallery</div>
            <div style="font-size:13px;color:var(--muted)">Rotating voices & credentials</div>
          </div>

          <div id="testimonial" class="testimonial" tabindex="0" style="margin-top:12px">
            <div class="quote">"A restorative arc that felt tailored — I slept deeply the next night."</div>
            <div class="meta">— L. (cohort participant)</div>
          </div>

          <div class="badges" aria-hidden="false">
            <div class="badge" tabindex="0" data-tip="Featured in a local wellness digest">Digest Pick</div>
            <div class="badge" tabindex="0" data-tip="Collaborated with neighborhood clinic to craft trauma-sensitive sessions">Clinic Partner</div>
            <div class="badge" tabindex="0" data-tip="Instructor holds somatic and music therapy certifications">Practitioner Certified</div>
          </div>
        </div>

      </section>

      <aside class="side-cta card">
        <div style="font-weight:800">Book a spot in the next cohort</div>
        <div style="color:var(--muted);font-size:14px">Cohorts fill quickly — reserve a place for the upcoming series.</div>
        <a class="cta-btn" href="book.html">Reserve your seat</a>
        <a style="color:var(--muted);font-size:13px;text-decoration:none" href="contact.html">Questions? Reach us at {{EMAIL}}</a>
      </aside>
    </div>
  </main>

  <svg class="pattern-wrap" viewBox="0 0 200 200" aria-hidden="true">
    <defs>
      <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#073238"/><stop offset="1" stop-color="#032e2b"/></linearGradient>
      <pattern id="p1" width="40" height="40" patternUnits="userSpaceOnUse" patternTransform="rotate(18)">
        <rect width="40" height="40" fill="url(#g1)" />
        <path d="M0 20h40M20 0v40" stroke="#0b3b3a" stroke-width="0.8"/>
        <circle cx="20" cy="20" r="4" fill="#064e4a" />
      </pattern>
    </defs>
    <rect width="200" height="200" fill="url(#p1)" opacity="0.85"></rect>
  </svg>

  <footer>
    <div style="max-width:900px;margin:0 auto">{{BUSINESS_NAME}} • Phone: {{PHONE}} • <a style="color:var(--accent);text-decoration:none" href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      // Testimonial rotation
      const items = [
        {q:'"A restorative arc that felt tailored — I slept deeply the next night."', m:'— L. (cohort participant)'},
        {q:'"Gentle, precise sound that let me drop the story and rest in my body."', m:'— R. (repeat attendee)'},
        {q:'"The facilitators are calm, clear, and quietly professional."', m:'— S. (clinic partner)'}
      ];
      let i=0; const node=document.getElementById('testimonial');
      function rotate(){
        i=(i+1)%items.length; node.innerHTML = '<div class="quote">'+items[i].q+'</div><div class="meta">'+items[i].m+'</div>';
      }
      setInterval(rotate,6000);

      // keyboard accessibility: left/right to cycle
      node.addEventListener('keydown',function(e){ if(e.key==='ArrowRight'){ rotate(); } if(e.key==='ArrowLeft'){ i=(i-1+items.length)%items.length; node.innerHTML = '<div class="quote">'+items[i].q+'</div><div class="meta">'+items[i].m+'</div>'; } });

      // badges: simple tooltip is from CSS ::after on hover/focus
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto; margin:0;background:#071018;color:#e9f6f2}
    header{display:flex;justify-content:space-between;padding:18px 22px;align-items:center}
    nav a{color:#9fbdb6;margin-left:16px;text-decoration:none;font-weight:700}
    main{padding:22px}
    .hero{background:linear-gradient(180deg,#071b1b,#031017);padding:20px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 8px}
    .q{margin-top:16px}
    details{background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
    summary{font-weight:700;cursor:pointer}
    .small{color:#9fbdb6;font-size:13px}
    .alert{background:#1d2f2e;padding:12px;border-radius:8px;border:1px solid rgba(122,215,198,0.08);margin-top:16px}
    footer{padding:20px;color:#8faea6}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html">About</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1>Questions & clarifications</h1>
      <p class="small">Short answers for common concerns about attending cohorts and sessions.</p>

      <div class="q">
        <details>
          <summary>What should I bring?</summary>
          <div style="margin-top:8px">A mat or blanket, a small pillow for your head, and a water bottle. We provide extra blankets on request.</div>
        </details>
      </div>

      <div class="q">
        <details>
          <summary>How loud is a session?</summary>
          <div style="margin-top:8px">Volumes are intentionally balanced to support a relaxing field. You choose a preferred intensity (gentle / medium / intense) when booking; facilitators will tune levels in the room accordingly.</div>
        </details>
      </div>

      <div class="q">
        <details>
          <summary>Are cohorts for beginners?</summary>
          <div style="margin-top:8px">Yes. Cohorts are structured to welcome beginners while offering deeper practice for returning participants.</div>
        </details>
      </div>

      <div class="q">
        <details>
          <summary>Contraindications and safety</summary>
          <div style="margin-top:8px">Sound can be powerful. If you have epilepsy, certain heart conditions, are pregnant, have photosensitivity, or recent head/neck injuries, consult your healthcare provider before attending. Also notify facilitators if you are on medication that makes you drowsy or if you use medical devices. We offer reduced-intensity options and can advise which cohorts are appropriate.</div>
        </details>
      </div>

      <div class="q">
        <details>
          <summary>Can I arrive late or leave early?</summary>
          <div style="margin-top:8px">We recommend arriving 10–15 minutes early to settle. Late arrivals can be accommodated quietly; if you must leave early, please inform a facilitator beforehand.</div>
        </details>
      </div>

      <div class="q">
        <details>
          <summary>Are there refund or transfer policies?</summary>
          <div style="margin-top:8px">Because cohorts are small and capacity-controlled, transfers are permitted up to 72 hours before the first meeting. Refunds follow the cohort policy listed on the booking page.</div>
        </details>
      </div>

      <div class="alert">
        If you have specific medical concerns or are attending as part of a therapeutic plan, contact us at <a style="color:#7ad7c6;text-decoration:none" href="mailto:{{EMAIL}}">{{EMAIL}}</a> before booking.
      </div>
    </section>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto">Questions still? Call us at {{PHONE}} • <a href="contact.html" style="color:#7ad7c6;text-decoration:none">Contact page</a></div>
  </footer>

  <script>
    // Enhanced UX: open first detail by default
    (function(){const d=document.querySelectorAll('details'); if(d.length) d[0].open=true;} )();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041616;--card:#072426;--muted:#9bd8cf;--accent:#7ad7c6}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto;background:linear-gradient(180deg,var(--bg),#011213);color:#eaf8f4}
    header{display:flex;justify-content:space-between;padding:18px 22px;align-items:center}
    nav a{color:#94d9cf;margin-left:16px;text-decoration:none;font-weight:700}
    main{padding:26px}
    .grid{display:grid;grid-template-columns:1fr 380px;gap:22px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 10px}
    .mixer{display:flex;gap:10px;margin-top:12px}
    .mixer button{padding:10px 12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);cursor:pointer}
    .mixer button.active{background:var(--accent);color:#022a26;font-weight:800}
    .programs{display:grid;gap:12px;margin-top:14px}
    .prog{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:800;color:var(--accent)}
    form .row{display:flex;flex-direction:column;margin-bottom:10px}
    input,select{padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:#eaf8f4}
    .submit{background:var(--accent);color:#022a26;padding:12px;border-radius:10px;border:none;font-weight:800;cursor:pointer;margin-top:10px}
    .note{font-size:13px;color:#98d9cf;margin-top:8px}
    .upcoming{font-size:14px;color:#c8efe6}
    .contra{background:#161f1f;padding:10px;border-radius:8px;border:1px solid rgba(122,215,198,0.06);margin-top:12px}
    @media (max-width:960px){.grid{grid-template-columns:1fr}.mixer{flex-wrap:wrap}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="events.html">Calendar</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Pricing</a>
      <a href="about.html">About</a>
      <a href="book.html" style="color:var(--accent)">Reserve</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <section class="card">
        <h1>Choose your sound preference</h1>
        <p class="note">Pick an intensity and we'll highlight the cohort rhythm and recommended tools.</p>

        <div class="mixer" role="tablist" aria-label="Sound intensity">
          <button id="gentle" class="active" role="tab" aria-selected="true">Gentle</button>
          <button id="medium" role="tab">Medium</button>
          <button id="intense" role="tab">Intense</button>
        </div>

        <div class="programs" id="programs">
          <!-- program cards updated by JS -->
        </div>

        <div class="contra">
          <strong>Contraindications</strong>
          <div style="margin-top:6px;color:#bfeee6">Please consult medical advice if you have epilepsy, heart device implants, are pregnant, have recent head/neck injury, or other acute conditions. If in doubt, email us at <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a>.</div>
        </div>
      </section>

      <aside class="card">
        <div style="font-weight:800">Reserve a cohort spot</div>
        <div class="upcoming" id="nextEvent">Next cohort: Loading…</div>

        <form id="bookForm" style="margin-top:12px">
          <div class="row">
            <label for="name">Full name</label>
            <input id="name" name="name" required />
          </div>
          <div class="row">
            <label for="email">Email</label>
            <input id="email" name="email" type="email" required />
          </div>
          <div class="row">
            <label for="cohort">Choose cohort</label>
            <select id="cohort" name="cohort"></select>
          </div>
          <div class="row">
            <label for="intensity">Preferred intensity</label>
            <select id="intensity" name="intensity">
              <option value="gentle">Gentle</option>
              <option value="medium">Medium</option>
              <option value="intense">Intense</option>
            </select>
          </div>
          <button class="submit" type="submit">Hold my spot</button>
        </form>

        <div style="margin-top:10px;color:var(--muted);font-size:13px">Questions? Call {{PHONE}} or email <a style="color:var(--accent);text-decoration:none" href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </aside>
    </div>
  </main>

  <script>
    (function(){
      // Cohort data (example) — in a full app this would be fetched
      const cohorts = [
        {id:'cohort-1',name:'River Cohort — Early Evenings (4 weeks)',start:'2026-03-02',spots:6,price:'$160 — sliding'},
        {id:'cohort-2',name:'Lumen Series — Weekend Intensives (2 weekends)',start:'2026-03-20',spots:8,price:'$220 — cohort rate'},
        {id:'cohort-3',name:'Anchor Run — Morning Rhythm (6 weeks)',start:'2026-04-06',spots:5,price:'$300 — member discount'}
      ];

      // Program recommendations per intensity
      const programs = {
        gentle:[
          {title:'Moonfall Drift — slow bowls & breath cues',desc:'For deep unwinding. Best after work or before sleep.',price:'Suggested: $160'},
          {title:'Soft Layer Session — subtle chimes & hum',desc:'A low-volume practice to settle the nervous system.',price:'Suggested: $120'}
        ],
        medium:[
          {title:'Tide Reset — layered bowls with choral overtones',desc:'For steady recalibration and clearer attention.',price:'Suggested: $180'},
          {title:'Balanced Arc — bowls, gongs, and guided breath',desc:'Designed for midday refreshes.',price:'Suggested: $150'}
        ],
        intense:[
          {title:'Edges — deeper gong textures & vocal work',desc:'For cathartic release; prior exposure recommended.',price:'Suggested: $240'},
          {title:'Deep Resonance Intensive — sustained harmonics',desc:'For experienced listeners seeking strong somatic response.',price:'Suggested: $260'}
        ]
      };

      // Fill cohort select and next-event module
      const cohortSelect = document.getElementById('cohort');
      const nextEvent = document.getElementById('nextEvent');
      cohorts.forEach(c=>{ const opt=document.createElement('option'); opt.value=c.id; opt.textContent=c.name+' — starts '+c.start+' • '+c.spots+' seats • '+c.price; cohortSelect.appendChild(opt); });
      nextEvent.textContent = 'Next cohort starts '+cohorts[0].start+' — '+cohorts[0].name;

      // Mixer buttons
      const gentleBtn=document.getElementById('gentle');
      const mediumBtn=document.getElementById('medium');
      const intenseBtn=document.getElementById('intense');
      const btns=[gentleBtn,mediumBtn,intenseBtn];
      const programsNode=document.getElementById('programs');

      function renderPrograms(level){
        programsNode.innerHTML='';
        (programs[level]||[]).forEach(p=>{
          const el=document.createElement('div'); el.className='prog';
          el.innerHTML = '<div><div style="font-weight:800">'+p.title+'</div><div style="color:var(--muted);font-size:13px;margin-top:6px">'+p.desc+'</div></div><div class="price">'+p.price+'</div>';
          programsNode.appendChild(el);
        });
      }

      function setActive(btn){ btns.forEach(b=>b.classList.remove('active')); btn.classList.add('active'); }

      gentleBtn.addEventListener('click',()=>{ setActive(gentleBtn); renderPrograms('gentle'); document.getElementById('intensity').value='gentle'; });
      mediumBtn.addEventListener('click',()=>{ setActive(mediumBtn); renderPrograms('medium'); document.getElementById('intensity').value='medium'; });
      intenseBtn.addEventListener('click',()=>{ setActive(intenseBtn); renderPrograms('intense'); document.getElementById('intensity').value='intense'; });

      // Initialize default
      renderPrograms('gentle');

      // Form submit (local-only) — simulate reservation
      document.getElementById('bookForm').addEventListener('submit',function(e){
        e.preventDefault();
        const name = this.name.value.trim();
        const email = this.email.value.trim();
        const cohort = this.cohort.value;
        const intensity = this.intensity.value;
        if(!name || !email){ alert('Please provide your name and email.'); return; }
        // Simulate booking: show confirmation and CTA different phrasing
        alert('Thanks, '+name+"! We've held a provisional seat for you in "+(document.querySelector('#cohort option:checked').text)+". Check your email for confirmation and payment details.");
        // In a real flow: POST to booking endpoint
        this.reset(); renderPrograms('gentle'); setActive(gentleBtn);
      });

      // Sync intensity select with mixer
      document.getElementById('intensity').addEventListener('change',function(){
        const v=this.value; if(v==='gentle') gentleBtn.click(); if(v==='medium') mediumBtn.click(); if(v==='intense') intenseBtn.click();
      });

    })();
  </script>
</body>
</html>"} 
